import { DEFAULT_RENDERER_DEFINITIONS, } from '@file-viewer/core';
const hangulDefinition = DEFAULT_RENDERER_DEFINITIONS.find(definition => definition.id === 'office-hangul');
if (!hangulDefinition)
    throw new Error('@file-viewer/renderer-hangul could not locate the shared HWP/HWPX definition.');
export const hangulRendererDefinition = hangulDefinition;
export const renderFileViewerHangul = (buffer, target, type, context) => import('./hangul.js').then(({ default: renderHangul }) => renderHangul(buffer, target, type, context));
export const hangulRenderer = {
    id: 'file-viewer-renderer-hangul',
    label: 'Flyfish File Viewer HWP/HWPX renderer',
    definitions: [hangulRendererDefinition],
    handlers: [{ rendererId: hangulRendererDefinition.id, handler: renderFileViewerHangul }],
};
export { DEFAULT_HANGUL_PARSE_LIMITS } from './limits.js';
export const parseHangulDocument = async (...args) => {
    const parser = await import('./hangul.parser.js');
    return parser.parseHangulDocument(...args);
};
export default hangulRenderer;
